import {chromium} from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch({args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1280, height: 800}});

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error' || msg.type() === 'warning') errors.push(`[${msg.type()}] ${msg.text()}`);
});
page.on('pageerror', (err) => errors.push(`[pageerror] ${err.message}`));

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('canvas');

// Геометрия: график должен занимать контейнер карточки.
const geo = await page.evaluate(() => {
  const canvas = document.querySelector('canvas');
  const card = canvas.closest('[class*="card"]') ?? canvas.parentElement.parentElement;
  const cr = card.getBoundingClientRect();
  const r = canvas.getBoundingClientRect();
  const root = document.querySelector('h1').parentElement.parentElement.parentElement;
  return {
    canvas: {w: Math.round(r.width), h: Math.round(r.height)},
    card: {w: Math.round(cr.width), h: Math.round(cr.height)},
    canvasCount: document.querySelectorAll('canvas').length,
    rootH: Math.round(root.getBoundingClientRect().height),
  };
});
console.log('geometry', JSON.stringify(geo));

await page.screenshot({path: '/tmp/browsercheck/light.png'});

// Realtime: ждём несколько тиков (шаг 2 с) и проверяем, что график перерисовывается.
const pixelHash = () =>
  page.evaluate(() => {
    const c = document.querySelector('canvas');
    const ctx = c.getContext('2d');
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    let h = 0;
    for (let i = 0; i < d.length; i += 97) h = (h * 31 + d[i]) | 0;
    return h;
  });
const h1 = await pixelHash();
await page.waitForTimeout(4500);
const h2 = await pixelHash();
console.log('canvas changed after realtime ticks:', h1 !== h2);

// Переключение на тёмную тему.
await page.getByText('Тёмная', {exact: true}).click();
await page.waitForTimeout(800);
await page.screenshot({path: '/tmp/browsercheck/dark.png'});
console.log('dark screenshot saved');

// Ресайз контейнера: график должен растянуться.
await page.setViewportSize({width: 900, height: 600});
await page.waitForTimeout(800);
const geo2 = await page.evaluate(() => {
  const r = document.querySelector('canvas').getBoundingClientRect();
  return {w: Math.round(r.width), h: Math.round(r.height)};
});
console.log('after resize canvas', JSON.stringify(geo2));
await page.screenshot({path: '/tmp/browsercheck/resized.png'});

// Пара секунд работы в тёмной теме без ошибок.
await page.waitForTimeout(5000);
console.log('console errors/warnings:', errors.length ? errors : 'none');

await browser.close();

