grep -n "setContext" -B3 index.js | head -12; cd /tmp/browsercheck && cat > probe2.mjs <<'EOF'
import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1280, height: 800}});
await page.goto('http://127.0.0.1:5173/', {waitUntil: 'networkidle'});
await page.waitForSelector('canvas');
await page.waitForTimeout(500);
const info = await page.evaluate(() => {
  const root = document.querySelector('.yagr');
  const cs = getComputedStyle(root);
  const c = document.querySelector('canvas');
  const ctx = c.getContext('2d', {willReadFrequently: true});
  // Сканируем цвета в левой полосе, где должны быть подписи Y-оси
  const w = c.width, h = c.height;
  const d = ctx.getImageData(0, 0, Math.min(60, w), h).data;
  const colors = new Map();
  for (let i = 0; i < d.length; i += 4) {
    const k = `${d[i]},${d[i+1]},${d[i+2]},${d[i+3]}`;
    colors.set(k, (colors.get(k) || 0) + 1);
  }
  const top = [...colors.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
  return {
    rootClass: root.className,
    axisStroke: cs.getPropertyValue('--yagr-axis-stroke'),
    grid: cs.getPropertyValue('--yagr-grid'),
    fontFamilyVar: cs.getPropertyValue('--yagr-font-family'),
    canvasPx: [c.width, c.height],
    leftStripTopColors: top,
    rootRect: root.getBoundingClientRect().toJSON(),
    uWrap: !!document.querySelector('.u-wrap'),
  };
});
console.log(JSON.stringify(info, null, 1));
await browser.close();
EOF
